#!/bin/bash
set -e
cd /home/user

ls /home/user/metrics/ && echo "---" && cat /home/user/metrics/cpu_usage.log && echo "---" && cat /home/user/metrics/memory_usage.log && echo "---" && cat /home/user/metrics/disk_usage.log
python3 /home/user/metrics/process.py
echo 'from collections import defaultdict' > /home/user/metrics/process.py && echo 'cpu_values = []; host_cpu = defaultdict(list)' >> /home/user/metrics/process.py && echo 'with open("/home/user/metrics/cpu_usage.log") as f:' >> /home/user/metrics/process.py && echo '    for line in f:' >> /home/user/metrics/process.py && echo '        parts = line.split()' >> /home/user/metrics/process.py && echo '        if len(parts) < 3: continue' >> /home/user/metrics/process.py && echo '        try: cpu_val = float(parts[2])' >> /home/user/metrics/process.py && echo '        except ValueError: continue' >> /home/user/metrics/process.py && echo '        cpu_values.append(cpu_val); host_cpu[parts[0]].append(cpu_val)' >> /home/user/metrics/process.py && echo 'avg_cpu = round(sum(cpu_values)/len(cpu_values),1)' >> /home/user/metrics/process.py && echo 'peak_cpu = max(cpu_values)' >> /home/user/metrics/process.py && echo 'best_host_cpu,best_avg_cpu = None,-1' >> /home/user/metrics/process.py && echo 'for host in sorted(host_cpu.keys()):' >> /home/user/metrics/process.py && echo '    h_avg = sum(host_cpu[host])/len(host_cpu[host])' >> /home/user/metrics/process.py && echo '    if h_avg > best_avg_cpu: best_avg_cpu=h_avg; best_host_cpu=host' >> /home/user/metrics/process.py && python3 /home/user/metrics/process.py && echo "PART1 OK"
echo 'mem_used_total=0; mem_cap_total=0' >> /home/user/metrics/process.py && echo 'host_mem_used=defaultdict(int); host_mem_cap=defaultdict(int)' >> /home/user/metrics/process.py && echo 'with open("/home/user/metrics/memory_usage.log") as f:' >> /home/user/metrics/process.py && echo '    for line in f:' >> /home/user/metrics/process.py && echo '        line=line.strip()' >> /home/user/metrics/process.py && echo '        if not line or line.startswith("#"): continue' >> /home/user/metrics/process.py && echo '        parts=line.split()' >> /home/user/metrics/process.py && echo '        if len(parts)<3: continue' >> /home/user/metrics/process.py && echo '        try: used=int(parts[1]); total=int(parts[2])' >> /home/user/metrics/process.py && echo '        except ValueError: continue' >> /home/user/metrics/process.py && echo '        mem_used_total+=used; mem_cap_total+=total' >> /home/user/metrics/process.py && echo '        host_mem_used[parts[0]]+=used; host_mem_cap[parts[0]]+=total' >> /home/user/metrics/process.py && echo 'overall_mem_util=round(mem_used_total/mem_cap_total*100,1)' >> /home/user/metrics/process.py && echo 'best_host_mem,best_mem_pct=None,-1' >> /home/user/metrics/process.py && echo 'for host in sorted(host_mem_used.keys()):' >> /home/user/metrics/process.py && echo '    pct=host_mem_used[host]/host_mem_cap[host]*100' >> /home/user/metrics/process.py && echo '    if pct>best_mem_pct: best_mem_pct=pct; best_host_mem=host' >> /home/user/metrics/process.py && echo 'best_mem_pct_rounded=round(best_mem_pct,1)' >> /home/user/metrics/process.py && python3 /home/user/metrics/process.py && echo "PART2 OK"
echo 'disk_entries=[]' >> /home/user/metrics/process.py && echo 'with open("/home/user/metrics/disk_usage.log") as f:' >> /home/user/metrics/process.py && echo '    for line in f:' >> /home/user/metrics/process.py && echo '        line=line.rstrip("\n")' >> /home/user/metrics/process.py && echo '        if not line.strip(): continue' >> /home/user/metrics/process.py && echo '        parts=line.split()' >> /home/user/metrics/process.py && echo '        if len(parts)<3: continue' >> /home/user/metrics/process.py && echo '        try: cap_gb=float(parts[-1]); used_gb=float(parts[-2])' >> /home/user/metrics/process.py && echo '        except ValueError: continue' >> /home/user/metrics/process.py && echo '        mount=" ".join(parts[:-2])' >> /home/user/metrics/process.py && echo '        if used_gb>cap_gb: continue' >> /home/user/metrics/process.py && echo '        disk_entries.append((mount,used_gb,cap_gb))' >> /home/user/metrics/process.py && echo 'tcap=sum(e[2] for e in disk_entries)' >> /home/user/metrics/process.py && echo 'tused=sum(e[1] for e in disk_entries)' >> /home/user/metrics/process.py && echo 'total_disk_cap=int(tcap)' >> /home/user/metrics/process.py && echo 'overall_disk_util=round(tused/tcap*100,1)' >> /home/user/metrics/process.py && echo 'best_mount,best_disk_pct=None,-1' >> /home/user/metrics/process.py && echo 'for mount,used,cap in disk_entries:' >> /home/user/metrics/process.py && echo '    pct=used/cap*100' >> /home/user/metrics/process.py && echo '    if pct>best_disk_pct: best_disk_pct=pct; best_mount=mount' >> /home/user/metrics/process.py && echo 'best_disk_pct_rounded=round(best_disk_pct,1)' >> /home/user/metrics/process.py && python3 /home/user/metrics/process.py && echo "PART3 OK"
echo 'cpu_status="WARN" if avg_cpu>75 else "OK"' >> /home/user/metrics/process.py && echo 'mem_status="WARN" if overall_mem_util>80 else "OK"' >> /home/user/metrics/process.py && echo 'disk_status="WARN" if overall_disk_util>70 else "OK"' >> /home/user/metrics/process.py && echo 'peak_str=str(peak_cpu) if peak_cpu!=int(peak_cpu) else str(int(peak_cpu))' >> /home/user/metrics/process.py && echo 'lines=[' >> /home/user/metrics/process.py && echo '    "=== CAPACITY PLANNING REPORT ===","",' >> /home/user/metrics/process.py && echo '    "[CPU]",' >> /home/user/metrics/process.py && echo '    f"Average Usage: {avg_cpu}%",' >> /home/user/metrics/process.py && echo '    f"Peak Usage: {peak_str}%",' >> /home/user/metrics/process.py && echo '    f"Busiest Host: {best_host_cpu}","",' >> /home/user/metrics/process.py && echo '    "[MEMORY]",' >> /home/user/metrics/process.py && echo '    f"Overall Utilization: {overall_mem_util}%",' >> /home/user/metrics/process.py && echo '    f"Total Used: {mem_used_total} MB",' >> /home/user/metrics/process.py && echo '    f"Most Loaded Host: {best_host_mem} ({best_mem_pct_rounded}%)","",' >> /home/user/metrics/process.py && echo '    "[DISK]",' >> /home/user/metrics/process.py && echo '    f"Overall Utilization: {overall_disk_util}%",' >> /home/user/metrics/process.py && echo '    f"Total Capacity: {total_disk_cap} GB",' >> /home/user/metrics/process.py && echo '    f"Fullest Mount: {best_mount} ({best_disk_pct_rounded}%)","",' >> /home/user/metrics/process.py && echo '    "[SUMMARY]",' >> /home/user/metrics/process.py && echo '    f"CPU Status: {cpu_status}",' >> /home/user/metrics/process.py && echo '    f"Memory Status: {mem_status}",' >> /home/user/metrics/process.py && echo '    f"Disk Status: {disk_status}",' >> /home/user/metrics/process.py && echo ']' >> /home/user/metrics/process.py && echo 'with open("/home/user/metrics/capacity_report.txt","w") as f:' >> /home/user/metrics/process.py && echo '    f.write("\n".join(lines)+"\n")' >> /home/user/metrics/process.py && python3 /home/user/metrics/process.py && echo "DONE"
cat /home/user/metrics/capacity_report.txt
